const $=selector=>document.querySelector(selector);
const icons={chat:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9H13a8.5 8.5 0 0 1 8 8v.5Z"/>',send:'<path d="m22 2-7 20-4-9L2 9 22 2Zm-11 11L22 2"/>',quote:'<path d="M3 6h7v7H5a4 4 0 0 1-2 4m11-11h7v7h-5a4 4 0 0 1-2 4"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>'};
const svg=name=>`<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={mode:'task',actor:'林悦',permission:'execute',working:false,reference:null,count:0};
const editor=$('.ws-inline-editor');const thread=$('.ws-chat-thread');const userTemplate=$('.ws-chat-message.user').cloneNode(true);const agentTemplate=$('.ws-chat-message.agent').cloneNode(true);const originalAgentText=$('.ws-chat-message.agent .ws-markdown').textContent.trim();
const context=$('.ws-chatbox-context');const contextHtml=context.innerHTML;
// Keep the production Agent/project triggers in their actual positions.
context.insertAdjacentHTML('afterbegin',`<div class="collab-mode" role="group" aria-label="发送模式"><button type="button" data-mode="task" aria-pressed="true">发给 Agent</button><button type="button" data-mode="discussion" aria-pressed="false">讨论</button></div>`);
const send=$('.ws-chat-send');send.type='button';send.removeAttribute('disabled');
$('.ws-chat-appbar-context > span').innerHTML='Alex 的会话 · Steer · 2 位参与者';
const appbar=$('.ws-chat-appbar');const headerControls=document.createElement('div');headerControls.className='collab-members';headerControls.innerHTML=`<span class="collab-avatar">A</span><span class="collab-avatar guest">林</span><button type="button" id="permissions" title="访问权限">${svg('users')}<span>访问权限</span></button>`;appbar.querySelectorAll('.ws-chat-share-trigger,.ws-chat-review-trigger').forEach(e=>e.remove());appbar.append(headerControls);
const demo=document.createElement('div');demo.className='collab-demo';demo.innerHTML=`<span>协作交互原型</span><select id="demo-actor" aria-label="演示发言人"><option>林悦</option><option>Alex</option></select><select id="demo-role" aria-label="演示权限"><option value="execute">可执行</option><option value="discuss">可讨论</option><option value="view">可查看</option></select><button type="button" id="demo-running">模拟执行中</button><button type="button" id="demo-reset">重置</button>`;$('.ws-sidebar-footer').prepend(demo);
const mobileDemo=document.createElement('button');mobileDemo.type='button';mobileDemo.className='collab-mobile-demo';mobileDemo.id='mobile-demo';mobileDemo.innerHTML='演示';appbar.append(mobileDemo);
const ref=document.createElement('div');ref.className='collab-reference';ref.hidden=true;$('.ws-inline-composer').prepend(ref);
function showReference(){ref.hidden=!state.reference;ref.innerHTML=state.reference?`<button type="button" data-command="remove-reference" aria-label="取消引用">${svg('close')}</button><span class="collab-reference-label">引用</span><span>${escape(state.reference.author)}：${escape(state.reference.text)}</span>`:'';}
function update(){const view=state.permission==='view';const noTask=state.permission!=='execute';if(noTask&&state.mode==='task')state.mode='discussion';document.querySelectorAll('[data-mode]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode));b.disabled=view||b.dataset.mode==='task'&&noTask});editor.contentEditable=String(!view);editor.setAttribute('aria-disabled',String(view));editor.dataset.placeholder=view?'你可以查看此会话，暂无发送权限':state.mode==='discussion'?'与参与者讨论，不会启动 Agent…':'提出问题或描述一项任务…';send.disabled=view||state.working&&state.mode==='task'||!editor.textContent.trim();send.title=send.getAttribute('aria-label')||'';send.setAttribute('aria-label',state.mode==='discussion'?'发送讨论':'发送给 Agent');send.title=state.mode==='discussion'?'发送讨论':'发送给 Builder';send.innerHTML=svg(state.mode==='discussion'?'chat':'send');$('.ws-composer-agent').style.display=state.mode==='discussion'?'none':'';$('.ws-composer-project').style.display=state.mode==='discussion'?'none':'';$('.ws-chat-mode-note').textContent=view?'仅查看 · 消息与执行结果':state.mode==='discussion'?'讨论对参与者可见；通过引用明确交给 Agent。':state.working?'Builder 正在执行 · 你可以切换到讨论继续补充。':'Builder · dev-machine / Codex · 同一会话内串行执行';showReference();}
function scroll(){const area=$('.ws-chat-center');area.scrollTop=area.scrollHeight;}
function discussion(author,text){const el=document.createElement('div');el.className='ws-chat-message collab-discussion';el.innerHTML=`<div class="collab-author"><span class="collab-avatar ${author==='林悦'?'guest':''}">${escape(author[0])}</span><span>${escape(author)}</span><small>讨论 · 刚刚</small></div><div class="collab-discussion-body">${escape(text).replace(/\n/g,'<br>')}</div><div class="ws-chat-message-actions"><button type="button" class="collab-handoff" data-discussion="${++state.count}" aria-label="引用并交给 Agent" title="引用并交给 Agent">${svg('quote')}<span>交给 Agent</span></button></div>`;el.dataset.author=author;el.dataset.text=text;thread.append(el);return el;}
function task(author,text,reference){const el=userTemplate.cloneNode(true);el.removeAttribute('id');el.querySelectorAll('.ws-chat-message-actions').forEach(e=>e.remove());const body=el.querySelector(':scope > div');body.innerHTML=`${reference?`<div class="collab-sent-reference">${escape(reference.author)}：${escape(reference.text)}</div>`:''}<p>${escape(text).replace(/\n/g,'<br>')}</p>`;el.insertAdjacentHTML('afterbegin',`<span class="collab-task-author">${escape(author)} · 发给 Builder</span>`);thread.append(el);}
function start(){if(state.working)return;state.working=true;const el=agentTemplate.cloneNode(true);el.classList.add('collab-current-run');el.querySelector('.ws-markdown').innerHTML='';el.querySelectorAll('.ws-chat-message-actions').forEach(n=>n.remove());const status=el.querySelector('.ws-chat-response-meta');status.classList.remove('is-complete');status.classList.add('is-running');status.textContent='Builder | Working · 0s';thread.append(el);state.started=Date.now();state.timer=setInterval(()=>{if(state.working)status.textContent=`Builder | Working · ${Math.floor((Date.now()-state.started)/1000)}s`;},1000);$('#demo-running').textContent='结束演示任务';update();scroll();}
function finish(){if(!state.working)return;state.working=false;clearInterval(state.timer);const el=$('.collab-current-run');el.classList.remove('collab-current-run');const status=el.querySelector('.ws-chat-response-meta');status.classList.remove('is-running');status.classList.add('is-complete');status.textContent=`Builder | Completed in ${Math.max(1,Math.floor((Date.now()-state.started)/1000))}s ›`;el.querySelector('.ws-markdown').innerHTML='<p>这是一条演示回复：已收到本轮任务与显式引用的讨论。实际执行时，会在这里继续显示结果。</p>';$('#demo-running').textContent='模拟执行中';update();scroll();}
function submit(){const text=editor.textContent.trim();if(!text||send.disabled)return;if(state.mode==='discussion'){discussion(state.actor,text)}else{task(state.actor,text,state.reference);start()}editor.textContent='';state.reference=null;update();scroll();editor.focus();}
function openPermissions(){const d=$('#collab-dialog');d.innerHTML=`<button class="collab-dialog-close" data-command="close-dialog" aria-label="关闭">${svg('close')}</button><h2>会话访问权限</h2><p>此会话属于 Alex。当前以 ${escape(state.actor)} 身份体验。</p><div class="collab-permission-row"><span>查看</span><small>阅读消息与 Agent 结果</small></div><div class="collab-permission-row"><span>讨论</span><small>阅读并发送讨论，不启动 Agent</small></div><div class="collab-permission-row"><span>执行</span><small>讨论并发起任务，使用 Alex 授权的执行环境</small></div><p>讨论不会自动进入 Agent 的执行上下文。通过“交给 Agent”引用，补充要求并发送后才执行。</p><footer><button data-command="close-dialog">知道了</button></footer>`;d.showModal();}
const d=document.createElement('dialog');d.id='collab-dialog';document.body.append(d);
editor.addEventListener('input',update);editor.addEventListener('keydown',event=>{if(event.isComposing)return;if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();submit()}});send.addEventListener('click',submit);$('.ws-chatbox').addEventListener('submit',event=>{event.preventDefault();submit()});
document.addEventListener('click',event=>{const mode=event.target.closest('[data-mode]');if(mode){state.mode=mode.dataset.mode;update();editor.focus();return}const handoff=event.target.closest('[data-discussion]');if(handoff){if(state.permission!=='execute'){openPermissions();return}const message=handoff.closest('.collab-discussion');state.reference={author:message.dataset.author,text:message.dataset.text};state.mode='task';update();editor.focus();return}const command=event.target.closest('[data-command]')?.dataset.command;if(command==='remove-reference'){state.reference=null;update();editor.focus()}if(command==='close-dialog')d.close();if(event.target.closest('#permissions'))openPermissions();if(event.target.closest('#demo-running'))state.working?finish():start();if(event.target.closest('#demo-reset'))location.reload();if(event.target.closest('#mobile-demo')){d.innerHTML=`<h2>原型演示</h2><p>不会发送真实消息或执行任务。</p><label>发言人<select id="mobile-actor"><option ${state.actor==='林悦'?'selected':''}>林悦</option><option ${state.actor==='Alex'?'selected':''}>Alex</option></select></label><label>权限<select id="mobile-role"><option value="execute">可执行</option><option value="discuss">可讨论</option><option value="view">可查看</option></select></label><footer><button data-command="close-dialog">完成</button></footer>`;d.showModal();$('#mobile-role').value=state.permission;}
// Production controls outside this interaction are retained visually.
if(event.target.closest('.ws-chat-message.agent button[title="引用回复"]')){state.reference={author:'Builder',text:originalAgentText};state.mode='task';update();editor.focus()}
});
document.addEventListener('change',event=>{if(['demo-actor','mobile-actor'].includes(event.target.id)){state.actor=event.target.value;$('#demo-actor').value=state.actor}if(['demo-role','mobile-role'].includes(event.target.id)){state.permission=event.target.value;$('#demo-role').value=state.permission;update()}});
$('.ws-chat-appbar button[aria-label="切换侧栏"]')?.addEventListener('click',()=>document.body.classList.toggle('collab-mobile-nav'));
thread.querySelector('.ws-chat-message.user').insertAdjacentHTML('afterbegin','<span class="collab-task-author">Alex · 发给 Builder</span>');
discussion('林悦','我来补充一个测试场景：手机从 Wi-Fi 切换到蜂窝网络时，需要保留原会话。');
update();
